/** Actual shared source lists and explicitly requested preparation evidence, with native history checks. */
public final class InstanceResearchAcceptance {
  record Case(long instance,int quests,List<Long> extras) {}
  static final List<Case> cases=List.of(new Case(27,7,List.of(289L,290L)),new Case(3,6,List.of(22L,23L)),new Case(34,8,List.of()));
  static final Map<Integer,String> slots=Map.ofEntries(Map.entry(1,"Head"),Map.entry(2,"Neck"),Map.entry(3,"Shoulder"),Map.entry(5,"Chest / robe"),Map.entry(6,"Waist"),Map.entry(7,"Legs"),Map.entry(8,"Feet"),Map.entry(9,"Wrist"),Map.entry(10,"Hands"),Map.entry(11,"Finger"),Map.entry(12,"Trinket"),Map.entry(13,"One-hand"),Map.entry(14,"Shield"),Map.entry(15,"Ranged"),Map.entry(16,"Back"),Map.entry(17,"Two-hand"),Map.entry(18,"Bag"),Map.entry(19,"Tabard"),Map.entry(21,"Main hand"),Map.entry(22,"Off hand"),Map.entry(23,"Held in off hand"),Map.entry(24,"Ammo"),Map.entry(25,"Thrown"),Map.entry(27,"Quiver"),Map.entry(28,"Relic"));
  static void check(boolean value,String message){JournalSnapshots.check(value,message);}
  static void size(int width)throws Exception{JournalSnapshots.edt(()->{JournalSnapshots.frame.setSize(width,900);return null;});JournalSnapshots.robot.delay(200);}
  static JComboBox<?> questChoice()throws Exception{return JournalSnapshots.edt(()->JournalSnapshots.all(JournalSnapshots.frame).stream().filter(c->c instanceof JComboBox<?> box&&box.isShowing()&&"Quest to research".equals(box.getAccessibleContext().getAccessibleName())).map(c->(JComboBox<?>)c).findFirst().orElseThrow());}
  static void selectedList(SharedLootPage shared,long id)throws Exception{
    JList<BossSummary> list=shared.listPage().extraLists();int index=JournalSnapshots.edt(()->{for(int i=0;i<list.getModel().getSize();i++)if(list.getModel().getElementAt(i).id()==id)return i;throw new AssertionError("Missing recorded shared list "+id);});
    JournalSnapshots.edt(()->{list.scrollRectToVisible(list.getCellBounds(index,index));return null;});Point point=JournalSnapshots.edt(()->{Rectangle bounds=list.getCellBounds(index,index);Point p=list.getLocationOnScreen();p.translate(bounds.x+bounds.width/2,bounds.y+bounds.height/2);return p;});JournalSnapshots.robot.mouseMove(point.x,point.y);JournalSnapshots.robot.mousePress(InputEvent.BUTTON1_DOWN_MASK);JournalSnapshots.robot.mouseRelease(InputEvent.BUTTON1_DOWN_MASK);JournalSnapshots.robot.waitForIdle();JournalSnapshots.robot.delay(200);check(JournalSnapshots.edt(()->list.getSelectedValue().id())==id,"Native selection opens exact source list #"+id);
  }
  public static void main(String[] args)throws Exception{
    if(args.length!=3||GraphicsEnvironment.isHeadless())throw new IllegalArgumentException("REVIEW_JAR DATABASE EMPTY_OUTPUT (isolated X11)");Path out=Path.of(args[2]);Files.createDirectories(out);try(var files=Files.list(out)){if(files.findAny().isPresent())throw new IllegalArgumentException("Output must be empty");}JournalSnapshots.out=out;var report=JournalSnapshots.report;report.add("Created: "+Instant.now());report.add("JAR SHA-256: "+JournalSnapshots.hash(Path.of(args[0])));report.add("Scope: actual source-backed instance records, native isolated X11, city music disabled");ExecutorService worker=Executors.newSingleThreadExecutor();
    try(var db=Database.open(Path.of(args[1]))){report.add("Database build: "+db.meta().get("build_id"));Repositories repos=Repositories.of(db);Map<Long,DetailPanels.LoadedInstance> loaded=new LinkedHashMap<>();for(Case c:cases){var snapshot=(DetailPanels.LoadedInstance)DetailPanels.load(new EntityRef(EntityKind.INSTANCE,c.instance()),repos).orElseThrow();check(snapshot.quests().size()==c.quests(),"Actual area quest count instance "+c.instance()+" = "+c.quests());if(c.instance()!=34)check(snapshot.detail().bosses().stream().filter(BossSummary::extraList).map(BossSummary::id).toList().equals(c.extras()),"Actual source-declared extra list identities instance "+c.instance());loaded.put(c.instance(),snapshot);}
      JournalSnapshots.edt(()->{Fonts.install();ThemeManager.apply(ThemeManager.Mode.DARK);JournalSnapshots.frame=new MainFrame();JournalSnapshots.controller=JournalSnapshots.wire(JournalSnapshots.frame,db,worker);JournalSnapshots.frame.setBounds(20,20,1280,900);JournalSnapshots.frame.setVisible(true);return null;});JournalSnapshots.robot=new Robot();JournalSnapshots.robot.setAutoDelay(55);
      for(Case c:cases){var snapshot=loaded.get(c.instance());size(1280);JournalSnapshots.edt(()->{JournalSnapshots.controller.open(new ViewTarget.Entity(new EntityRef(EntityKind.INSTANCE,c.instance())));return null;});ResearchAcceptance.until(()->JournalSnapshots.edt(()->JournalSnapshots.all(JournalSnapshots.frame).stream().anyMatch(component->component instanceof HeaderPanel header&&header.isShowing()&&snapshot.detail().summary().displayName().equals(header.title()))),"loaded exact instance guide "+c.instance());ResearchAcceptance.tab("Bosses & loot");JournalSnapshots.waitFor(InstancePage.class);InstancePage encounters=JournalSnapshots.find(InstancePage.class);long realCount=snapshot.detail().bosses().stream().filter(b->!b.extraList()).count();check(JournalSnapshots.edt(()->encounters.encounters().getModel().getSize())==realCount&&JournalSnapshots.edt(()->encounters.extraLists().getModel().getSize())==0,"Encounter list and count exclude extra source lists for instance "+c.instance());
        if(c.instance()!=34){ResearchAcceptance.tab("Shared loot");JournalSnapshots.waitFor(SharedLootPage.class);SharedLootPage shared=JournalSnapshots.find(SharedLootPage.class);
        if(c.extras().isEmpty()){check(shared.listPage()==null&&ResearchAcceptance.text().contains(SharedLootPage.EMPTY),"Dalaran missing shared list remains qualified unknown");JournalSnapshots.snap("instance-34-shared-empty");}
        else{
          AbstractButton evidence=JournalSnapshots.edt(()->JournalSnapshots.all(shared).stream().filter(component->component instanceof AbstractButton button&&button.isShowing()&&"About shared loot evidence".equals(button.getText())).map(component->(AbstractButton)component).findFirst().orElse(null));if(evidence!=null)JournalSnapshots.click(evidence);check(ResearchAcceptance.text().contains("Reported membership does not establish Forever drop confirmation"),"Explicit shared evidence disclosure qualifies presence, rates and eligible mobs");if(evidence!=null)JournalSnapshots.click(evidence);check(JournalSnapshots.edt(()->shared.listPage().extraLists().getModel().getSize())==c.extras().size(),"Shared workspace contains only source-declared extra lists");
          for(long id:c.extras()){selectedList(shared,id);BossSummary identity=snapshot.detail().bosses().stream().filter(b->b.id()==id).findFirst().orElseThrow();check(JournalSnapshots.edt(()->shared.listPage().extraLists().getSelectedValue().displayName()).equals(identity.displayName()),"Shared list retains original source name: "+identity.displayName());if(identity.objectId()!=null)check(ResearchAcceptance.text().contains("Recorded "+EntityKind.OBJECT.label()+" #"+identity.objectId())||JournalSnapshots.edt(()->JournalSnapshots.all(JournalSnapshots.frame).stream().anyMatch(component->component instanceof JButton button&&("Recorded "+EntityKind.OBJECT.label()+" #"+identity.objectId()+" →").equals(button.getText()))),"Shared list preserves recorded object identity #"+identity.objectId());JournalSnapshots.snap("instance-"+c.instance()+"-source-list-"+id);}
          size(420);report.add(JournalSnapshots.edt(()->"COMPACT GEOMETRY instance "+c.instance()+": shared="+shared.getSize()+", lists="+shared.listPage().getSize()+", source-list-visible="+shared.listPage().extraLists().getVisibleRect()+", loot-table-visible="+shared.listPage().lootTable().table().getVisibleRect()));JournalSnapshots.snap("instance-"+c.instance()+"-shared-compact");revealLoot(shared);JournalSnapshots.snap("instance-"+c.instance()+"-shared-compact-loot-scrolled");check(JournalSnapshots.edt(()->shared.listPage().getHeight())>=300&&JournalSnapshots.edt(()->shared.listPage().extraLists().getVisibleRect().height)>=18&&JournalSnapshots.edt(()->shared.listPage().lootTable().table().getVisibleRect().height)>=24,"Compact shared source list and actual loot rows both remain visible and usable");size(1280);
          Selection selection=filterSelection(snapshot,c);selectedList(shared,selection.listId());String slot=selection.slot();JournalSnapshots.selectChoice(JournalSnapshots.combo("loot-slot-filter"),slot);
          if(selection.member()!=null){
            LootRow row=selection.member();check(JournalSnapshots.edt(()->JournalSnapshots.lootRefs(shared.listPage()).contains(row.item())),"Known Forever slot filter retains actual shared-list member "+row.item().id());var table=shared.listPage().lootTable();int at=JournalSnapshots.edt(()->{for(int index=0;index<table.table().getRowCount();index++)if(TableLinks.refAt(table.table(),table.model(),index).filter(row.item()::equals).isPresent())return index;throw new AssertionError("Filtered source member missing");});JournalSnapshots.edt(()->{table.table().setRowSelectionInterval(at,at);table.table().scrollRectToVisible(table.table().getCellRect(at,0,true));table.table().requestFocusInWindow();return null;});ResearchAcceptance.key(KeyEvent.VK_ENTER);ResearchAcceptance.target(EntityKind.ITEM,row.item().id());ResearchAcceptance.loadedItem(row.item().id());
          }else{
            check(JournalSnapshots.edt(()->JournalSnapshots.lootRefs(shared.listPage()).isEmpty())&&ResearchAcceptance.text().contains("unknown"),"Missing shared-list equipment slots remain unknown rather than matching an active filter");JournalSnapshots.click(JournalSnapshots.button("Journal"));JournalSnapshots.waitFor(JournalHomePage.class);
          }
          JournalSnapshots.back();JournalSnapshots.waitFor(SharedLootPage.class);SharedLootPage restored=JournalSnapshots.find(SharedLootPage.class);check(JournalSnapshots.edt(()->restored.listPage().extraLists().getSelectedValue().id())==selection.listId()&&JournalSnapshots.edt(()->JournalSnapshots.comboUnchecked("loot-slot-filter").getSelectedItem().toString()).equals(slot),"Native Back restores Shared loot tab, exact source list and slot filter");JournalSnapshots.snap("instance-"+c.instance()+"-shared-filter-back");
        }
        }
        ResearchAcceptance.tab("Preparation research");JComboBox<?> quests=questChoice();check(JournalSnapshots.edt(quests::getItemCount)==c.quests()&&ResearchAcceptance.text().contains("Recorded quests for this area · "+c.quests()),"Preparation presents exact recorded area quest count "+c.quests());check(ResearchAcceptance.text().contains("No source-qualified instance access requirement recorded")&&JournalSnapshots.find(ChainPanel.class)==null,"Preparation leaves access unknown and quest inspection unloaded by default");
        if(c.instance()==27){JournalSnapshots.edt(()->{for(int index=0;index<quests.getItemCount();index++)if(((QuestSummary)quests.getItemAt(index)).id()==7848){quests.setSelectedIndex(index);return null;}throw new AssertionError("Expected recorded area quest7848 missing");});check(JournalSnapshots.find(ChainPanel.class)==null,"Selecting recorded quest7848 does not eagerly inspect or establish mandatory access");}
        for(int width:new int[]{1280,420}){size(width);JournalSnapshots.snap("instance-"+c.instance()+"-preparation-"+width);}size(1280);long questId=JournalSnapshots.edt(()->((QuestSummary)quests.getSelectedItem()).id());JournalSnapshots.click(JournalSnapshots.button("Inspect recorded prerequisites & items"));JournalSnapshots.waitFor(ChainPanel.class);ResearchAcceptance.until(()->ResearchAcceptance.text().contains("Quest required items")&&ResearchAcceptance.text().contains("Quest provided items"),"explicit quest required/provided categories");check(ResearchAcceptance.text().contains("They do not establish instance keys or entry requirements")&&ResearchAcceptance.text().contains("No source-qualified instance access requirement recorded"),"Inspected quest evidence remains separate from mandatory instance access");JournalSnapshots.click(ResearchAcceptance.prefix("Open quest: "));ResearchAcceptance.target(EntityKind.QUEST,questId);JournalSnapshots.waitFor(QuestPage.class);JournalSnapshots.back();JournalSnapshots.waitFor(ChainPanel.class);check(JournalSnapshots.edt(()->((QuestSummary)questChoiceUnchecked().getSelectedItem()).id())==questId,"Native Back restores inspected Preparation quest and evidence");size(420);JournalSnapshots.snap("instance-"+c.instance()+"-preparation-inspected-back");
      }
    }catch(Throwable failure){report.add("FAIL: "+failure);throw failure;}finally{if(JournalSnapshots.frame!=null)JournalSnapshots.edt(()->{JournalSnapshots.frame.dispose();return null;});worker.shutdownNow();Files.write(out.resolve("report.txt"),report);System.out.println(String.join("\n",report));}System.exit(0);
  }
  static void revealLoot(SharedLootPage shared)throws Exception{
    JTable table=shared.listPage().lootTable().table();JScrollPane outer=JournalSnapshots.edt(()->JournalSnapshots.all(shared.listPage()).stream().filter(component->component instanceof JScrollPane pane&&SwingUtilities.isDescendingFrom(table,pane)&&pane.getViewport().getVisibleRect().height>0).map(component->(JScrollPane)component).findFirst().orElseThrow());
    Point point=JournalSnapshots.edt(()->{Point p=outer.getViewport().getLocationOnScreen();p.translate(outer.getViewport().getWidth()/2,outer.getViewport().getHeight()/2);return p;});JournalSnapshots.robot.mouseMove(point.x,point.y);for(int pass=0;pass<8&&JournalSnapshots.edt(()->table.getVisibleRect().height)<24;pass++){JournalSnapshots.robot.mouseWheel(4);JournalSnapshots.robot.delay(150);}JournalSnapshots.report.add(JournalSnapshots.edt(()->"COMPACT SCROLLED loot table="+table.getVisibleRect()+", scroll="+outer.getVerticalScrollBar().getValue()+"/"+outer.getVerticalScrollBar().getMaximum()));
  }
  record Selection(long listId,LootRow member,String slot) {}
  static Selection filterSelection(DetailPanels.LoadedInstance snapshot,Case c){for(long id:c.extras())for(LootRow row:snapshot.clientLoot().lookup(id,snapshot.detail().difficulties().getFirst()))if(row.inventoryType()!=null&&slots.containsKey(row.inventoryType()))return new Selection(id,row,slots.get(row.inventoryType()));return new Selection(c.extras().getFirst(),null,"Hands");}
  static JComboBox<?> questChoiceUnchecked(){return JournalSnapshots.all(JournalSnapshots.frame).stream().filter(c->c instanceof JComboBox<?> box&&box.isShowing()&&"Quest to research".equals(box.getAccessibleContext().getAccessibleName())).map(c->(JComboBox<?>)c).findFirst().orElseThrow();}
}
